go.solution:
package main

import "fmt"

func pluralize(count int, noun string) string {
	// Go has no conditional expression, so a short if takes its place.
	if count == 1 {
		return noun
	}
	return noun + "s"
}

func main() {
	var count int
	var noun string
	fmt.Scan(&count, &noun)
	fmt.Println(count, pluralize(count, noun))
}
